query get($id: bigint!) {
  product_counter: campaign_products_aggregate(where: {campaign_id: {_eq: $id}}) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  campaign_products: campaign_products(
    where: {campaign_id: {_eq: $id}}
    order_by: {position: asc}
  ) {
    product {
      id
      title
      color_custom_label
      size_custom_label
      enable_custom_printarea
      printareas {
        id
        name
        display_name
        width
        height
        __typename
      }
      __typename
    }
    campaign_variants_aggregate(where: {variant: {available: {_eq: true}}}) {
      aggregate {
        count
        __typename
      }
      __typename
    }
    campaign_mockups_aggregate {
      aggregate {
        count
        __typename
      }
      __typename
    }
    campaign_image_mockups_aggregate: campaign_mockups_aggregate(
      where: {type: {_eq: "image"}}
    ) {
      aggregate {
        count
        __typename
      }
      __typename
    }
    __typename
  }
  campaign_artworks: campaign_artwork_printareas(
    where: {campaign_id: {_eq: $id}, deleted_at: {_is_null: true}}
  ) {
    artwork_id
    printarea_id
    __typename
  }
  variant_counter: campaign_variants_aggregate(
    where: {campaign_product: {campaign_id: {_eq: $id}}}
  ) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  campaign_variants: campaign_variants(
    where: {campaign_product: {campaign_id: {_eq: $id}}}
  ) {
    variant_id
    variant {
      product_id
      color
      size
      price
      fulfillment_linked_id
      printarea_id
      variant_printareas {
        printarea_id
        __typename
      }
      __typename
    }
    __typename
  }
}

query getData($limit: Int!) {
  products_connection(
    first: $limit
    where: {status: {_neq: "1"}}
    order_by: {id: desc}
  ) {
    edges {
      cursor
      node {
        id
        mockups(limit: 2) {
          id
          thumbnail
          preview_thumbnail
          __typename
        }
        title
        label
        internal_tags
        is_imported
        fulfillment {
          display_name
          __typename
        }
        __typename
      }
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    __typename
  }
}

